package com.graduation.snack.domain; import com.graduation.snack.auth.AuthService; import com.graduation.snack.common.ApiException; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController{private final GroupOrderRepository orders;private final GroupCampaignRepository campaigns;private final SnackProductRepository products;private final AuthService auth;public OrderController(GroupOrderRepository o,GroupCampaignRepository c,SnackProductRepository p,AuthService a){orders=o;campaigns=c;products=p;auth=a;}public record Create(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Positive Long campaignId,@jakarta.validation.constraints.Positive int quantity){}
@PostMapping @Transactional public GroupOrder create(@jakarta.validation.Valid @RequestBody Create x){if(x.quantity()<=0)throw ApiException.badRequest("数量必须大于 0");var c=campaigns.findById(x.campaignId()).orElseThrow(()->ApiException.notFound("团购不存在"));var now=LocalDateTime.now();if(!"ACTIVE".equals(c.getStatus())||now.isBefore(c.getStartTime())||now.isAfter(c.getEndTime()))throw ApiException.badRequest("团购当前不可下单");var p=products.findById(c.getProductId()).orElseThrow(()->ApiException.notFound("商品不存在"));if(p.getStock()<x.quantity())throw ApiException.badRequest("库存不足");p.setStock(p.getStock()-x.quantity());c.setSoldQuantity(c.getSoldQuantity()+x.quantity());products.save(p);campaigns.save(c);var o=new GroupOrder();o.setCampaignId(c.getId());o.setUserId(auth.currentUser().getId());o.setQuantity(x.quantity());o.setTotalAmount(c.getGroupPrice().multiply(java.math.BigDecimal.valueOf(x.quantity())));o.setStatus("PAID");return orders.save(o);}
@GetMapping public List<GroupOrder> list(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?orders.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():orders.findTop200ByUserIdOrderByIdDesc(u.getId());} }
